// Builds the Telegram + email message for a new inquiry, a reminder or an escalation.
const cfg = $('Config').first().json;
const esc = (s) => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const out = [];
for (const item of $input.all()) {
  const { inq, recipient, kind, tz, school_name } = item.json;
  if (!inq) throw new Error('Inquiry not found for notification');
  if (!recipient) throw new Error(`Inquiry ${inq.inquiry_id}: no recipient (check routing rules / escalation contact)`);
  const L = inq.lead || {};
  const fmt = (iso, opts) => iso ? new Intl.DateTimeFormat('en-GB', { timeZone: tz, ...opts }).format(new Date(iso)) : '';
  const hhmm = (iso) => fmt(iso, { hour: '2-digit', minute: '2-digit' });
  const dayTime = (iso) => fmt(iso, { weekday: 'short', hour: '2-digit', minute: '2-digit' });
  const channel = inq.channel === 'meta'
    ? (inq.platform === 'ig' ? 'Instagram lead form' : 'Facebook lead form')
    : ({ web: 'Website form', whatsapp: 'WhatsApp' }[inq.channel] || inq.channel);
  const langName = { ar: 'Arabic', en: 'English', fr: 'French', ur: 'Urdu', hi: 'Hindi' }[inq.language] || String(inq.language || '').toUpperCase();
  const mins = Math.round(Number(inq.minutes_open || 0));
  const headline = {
    new: inq.is_repeat ? '🔁 Returning family, new inquiry' : '🆕 New inquiry',
    reminder: `⏰ Still waiting: ${mins} min, not claimed yet`,
    escalation: `🚨 Escalation: unclaimed for ${mins} min`,
  }[kind] || '🆕 New inquiry';
  const claimUrl = `${cfg.public_base_url}/webhook/leadops/lead?t=${inq.public_token}&u=${encodeURIComponent(recipient.code)}`;
  const digits = String(L.phone_e164 || '').replace(/\D/g, '');
  const firstName = L.first_name || L.full_name || '';
  const greet = inq.language === 'ar'
    ? `مرحباً ${firstName}، معك ${recipient.name} من قسم القبول في ${school_name}. شكراً لتواصلكم معنا، متى يناسبكم أن نتحدث؟`
    : `Hello ${firstName}, this is ${recipient.name} from ${school_name} Admissions. Thank you for your inquiry. When would be a good time to talk?`;
  const waUrl = digits ? `https://wa.me/${digits}?text=${encodeURIComponent(greet)}` : null;
  const answers = Object.entries(inq.answers || {}).slice(0, 8);
  const due = inq.sla_due_at
    ? (inq.after_hours ? `Arrived after hours. Please pick up by ${dayTime(inq.sla_due_at)}.`
      : `Respond by ${hhmm(inq.sla_due_at)} (${inq.rule ? inq.rule.sla_minutes : '?'}-minute promise).`)
    : null;
  const lines = [
    `<b>${esc(headline)}</b>`,
    `${esc(channel)}${inq.campaign_name ? ' · ' + esc(inq.campaign_name) : ''}`,
    '',
    `<b>${esc(L.full_name || 'Unknown name')}</b>${langName ? ' · ' + esc(langName) : ''}`,
    L.phone_e164 ? `📞 ${esc(L.phone_e164)}` : null,
    L.email ? `✉️ ${esc(L.email)}` : null,
    ...answers.map(([k, v]) => `• ${esc(k)}: ${esc(v)}`),
    inq.message ? `💬 "${esc(String(inq.message).slice(0, 300))}"` : null,
    '',
    inq.is_repeat && L.inquiry_count > 1 ? `Inquiry number ${L.inquiry_count} from this family.` : null,
    kind === 'escalation' && inq.assigned_agent ? `Assigned to ${esc(inq.assigned_agent.name)}, not claimed yet.` : null,
    due ? esc(due) : null,
    inq.is_test ? '<i>Test inquiry</i>' : null,
  ].filter((l) => l !== null);
  const keyboard = [[{ text: kind === 'escalation' ? 'Open and take over' : 'Open and claim', url: claimUrl }]];
  if (waUrl) keyboard.push([{ text: 'WhatsApp with greeting', url: waUrl }]);
  const rows = [
    ['Channel', channel + (inq.campaign_name ? ' · ' + inq.campaign_name : '')],
    ['Phone', L.phone_e164], ['Email', L.email], ['Language', langName],
    ...answers, ['Message', inq.message], ['Deadline', due],
  ].filter(([, v]) => v);
  const emailHtml = `<div style="font-family:Segoe UI,Arial,sans-serif;color:#12241F;max-width:560px">
<p style="font-size:16px;margin:0 0 4px"><b>${esc(headline)}</b></p>
<p style="font-size:22px;margin:0 0 16px">${esc(L.full_name || 'Unknown name')}</p>
<table style="border-collapse:collapse;font-size:14px">${rows.map(([k, v]) => `<tr><td style="padding:4px 16px 4px 0;color:#5E6E68;vertical-align:top">${esc(k)}</td><td style="padding:4px 0">${esc(v)}</td></tr>`).join('')}</table>
<p style="margin:20px 0"><a href="${esc(claimUrl)}" style="background:#0B6E4F;color:#fff;padding:12px 18px;border-radius:6px;text-decoration:none">${kind === 'escalation' ? 'Open and take over' : 'Open and claim'}</a></p>
</div>`;
  out.push({ json: {
    inquiry_id: inq.inquiry_id, kind, recipient_id: recipient.id, recipient_name: recipient.name,
    telegram_chat_id: recipient.telegram_chat_id || null, email: recipient.email || null,
    tg_text: lines.join('\n').replace(/\n{3,}/g, '\n\n'),
    tg_markup: { inline_keyboard: keyboard },
    email_subject: `${headline.replace(/^[^A-Za-z]+/, '')}: ${L.full_name || 'Unknown'} (${channel})`,
    email_html: emailHtml,
    claim_url: claimUrl,
    send_telegram: !!(recipient.telegram_chat_id && cfg.telegram_enabled),
    send_email: !!(recipient.email && cfg.email_enabled),
  } });
}
for (const o of out) {
  if (!o.json.send_telegram && !o.json.send_email) {
    throw new Error(`Agent "${o.json.recipient_name}" has no working notification channel: set agents.telegram_chat_id (and TELEGRAM_BOT_TOKEN) or agents.email (and SMTP_ENABLED=true)`);
  }
}
return out;

